INSERT INTO questions (id, section, topic, type, prompt, passage, options, answer, explanation, difficulty, position,
                       origin, created_at, topic_id, topic_label) VALUES
('orig-qa-001', 'QA', 'Profit, Loss & Discount', 'MCQ', 'A retailer marks an item at ₹144 after buying it for ₹120. He offers successive discounts of 10% and 5%, and then charges a delivery fee of ₹12. What is his net profit percentage on the cost price?', NULL, '["12.60%", "8.40%", "10.60%", "14.60%"]'::jsonb, '0', 'Selling price = 144 × 0.90 × 0.95 = ₹123.12; with the ₹12 fee he receives ₹135.12. Profit = 15.12 on 120 = 12.6%. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10001, 'BANK', now(), 'qa::arithmetic::profit-loss-discount', 'QA › Arithmetic › Profit, Loss & Discount'),
('orig-qa-002', 'QA', 'Mixtures & Alligation', 'MCQ', 'A solution contains acid and water in the ratio 3 : 4. When 252 litres of the solution are removed and replaced with water, the ratio of acid to water becomes 1 : 6. What was the initial volume of the solution?', NULL, '["756 litres", "378 litres", "441 litres", "504 litres"]'::jsonb, '1', 'Acid is 3/7 of the solution before and 1/7 after, so the acid kept is (1/7)/(3/7) = 1/3 of the original. Removing 252 litres kept 1 − 252/V = 1/3 of it, so V = 378 litres. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10002, 'BANK', now(), 'qa::arithmetic::mixtures-alligation', 'QA › Arithmetic › Mixtures & Alligation'),
('orig-qa-003', 'QA', 'Ratio & Proportion', 'MCQ', 'A and B start a business with capitals in the ratio 20 : 31. After 4 months A withdraws one-third of his capital, and after 6 months B increases his capital by 25%. If the profit at the end of the year is ₹26,600, what is A’s share?', NULL, '["₹8,205", "₹13,300", "₹9,025", "₹7,384"]'::jsonb, '0', 'A: 20×4 + (40/3)×8 = 186.67 units; B: 31×6 + 38.75×6 = 418.5 units. A’s share = 26600 × 186.67/605.17 ≈ ₹8,205. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10003, 'BANK', now(), 'qa::arithmetic::ratio-proportion', 'QA › Arithmetic › Ratio & Proportion'),
('orig-qa-004', 'QA', 'Time, Speed & Distance', 'MCQ', 'A vehicle covers a 135 km route, travelling the first half at 7 km/h and the second half at 9 km/h, with a 13-minute halt at the midpoint. What is its average speed for the whole journey, including the halt? (Rounded to two decimals.)', NULL, '["8.00 km/h", "7.78 km/h", "7.88 km/h", "7.65 km/h"]'::jsonb, '1', 'Time = 67.5/7 + 67.5/9 + 13/60 = 9.643 + 7.5 + 0.217 = 17.36 h. Average speed = 135/17.36 ≈ 7.78 km/h. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10004, 'BANK', now(), 'qa::arithmetic::time-speed-distance', 'QA › Arithmetic › Time, Speed & Distance'),
('orig-qa-005', 'QA', 'Simple & Compound Interest', 'MCQ', '₹12,000 is invested at 8% per annum compounded annually. At the end of two years the investor withdraws ₹5,598. What balance remains immediately after the withdrawal?', NULL, '["₹8,322.00", "₹8,898.80", "₹7,898.80", "₹8,398.80"]'::jsonb, '3', 'Amount after two years = 12000 × 1.08² = ₹13,996.80. After withdrawing ₹5,598, ₹8,398.80 remains. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10005, 'BANK', now(), 'qa::arithmetic::simple-compound-interest', 'QA › Arithmetic › Simple & Compound Interest'),
('orig-qa-006', 'QA', 'Set theory', 'MCQ', 'In a test, the numbers of candidates who cleared Section I and Section II are in the ratio 5 : 7. 250 candidates cleared at least one section, and the number who cleared both is 20% of these 250. How many candidates cleared only Section I?', NULL, '["50", "125", "75", "100"]'::jsonb, '2', 'Both = 50, so I + II = 250 + 50 = 300 and I = 300 × 5/12 = 125. Only Section I = 125 − 50 = 75. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10006, 'BANK', now(), 'qa::modern-maths::set-theory', 'QA › Modern Maths › Set theory'),
('orig-qa-007', 'QA', 'Quadratic equations', 'MCQ', 'Let f(x) = x² − 5x + 6. If a real number t satisfies f(t + 1) = f(t − 1), find t.', NULL, '["1.5", "3", "3.5", "2.5"]'::jsonb, '3', 'f(t+1) − f(t−1) = 4t − 10 (the x² terms differ by 4t and the −5x terms by −10). Setting this to 0 gives t = 2.5. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10007, 'BANK', now(), 'qa::algebra::quadratic-equations', 'QA › Algebra › Quadratic equations'),
('orig-qa-008', 'QA', 'Quadratic equations', 'MCQ', 'The roots of x² − 15x + k = 0 are positive integers that differ by 3. What is the value of k?', NULL, '["36", "54", "50", "56"]'::jsonb, '1', 'The roots add up to 15 and differ by 3, so they are 6 and 9, and k = 6 × 9 = 54. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10008, 'BANK', now(), 'qa::algebra::quadratic-equations', 'QA › Algebra › Quadratic equations'),
('orig-qa-009', 'QA', 'Surds & Indices', 'MCQ', 'If 2ˣ + 2⁻ˣ = 12, what is the value of 4ˣ + 4⁻ˣ?', NULL, '["142", "146", "140", "144"]'::jsonb, '0', 'Squaring: 4ˣ + 2 + 4⁻ˣ = 144, so 4ˣ + 4⁻ˣ = 142. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10009, 'BANK', now(), 'qa::algebra::surds-indices', 'QA › Algebra › Surds & Indices'),
('orig-qa-010', 'QA', 'Functions & Graphs', 'MCQ', 'A function g satisfies g(x + y) = g(x)·g(y) for all real x and y, with g(1) = 5 and g(0) = 1. Find g(−1).', NULL, '["5", "−5", "1/5", "−1/5"]'::jsonb, '2', 'g(1)·g(−1) = g(0) = 1, so g(−1) = 1/5. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10010, 'BANK', now(), 'qa::algebra::functions-graphs', 'QA › Algebra › Functions & Graphs'),
('orig-qa-011', 'QA', 'Inequalities & Modulus', 'MCQ', 'How many distinct real solutions does |x − 6| + |x − 11| = 24 have?', NULL, '["2", "Infinitely many", "0", "1"]'::jsonb, '0', 'The minimum of the left side is 5 (for 6 ≤ x ≤ 11). Since 24 > 5 there is one solution on each side: x = −3.5 and x = 20.5. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10011, 'BANK', now(), 'qa::algebra::inequalities-modulus', 'QA › Algebra › Inequalities & Modulus'),
('orig-qa-012', 'QA', 'Triangles', 'MCQ', 'A triangle has sides 13, 14 and 15. What is its area?', NULL, '["42", "96", "91", "84"]'::jsonb, '3', 'With s = 21, Heron’s formula gives √(21 × 8 × 7 × 6) = √7056 = 84. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10012, 'BANK', now(), 'qa::geometry-mensuration::triangles', 'QA › Geometry & Mensuration › Triangles'),
('orig-qa-013', 'QA', '3D Mensuration', 'MCQ', 'A right circular cylinder of radius 6 cm and height 12 cm is melted and recast into solid spheres of radius 1 cm. How many complete spheres can be made?', NULL, '["324", "162", "432", "325"]'::jsonb, '0', 'Volume ratio = (π × 36 × 12)/(4π/3) = 432 × 3/4 = 324. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10013, 'BANK', now(), 'qa::geometry-mensuration::3d-mensuration', 'QA › Geometry & Mensuration › 3D Mensuration'),
('orig-qa-014', 'QA', 'Circles', 'MCQ', 'A chord of length 24 cm is drawn in a circle of radius 13 cm. What is the distance of the chord from the centre?', NULL, '["6 cm", "12 cm", "7 cm", "5 cm"]'::jsonb, '3', 'Half the chord is 12, so the distance is √(13² − 12²) = 5 cm. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10014, 'BANK', now(), 'qa::geometry-mensuration::circles', 'QA › Geometry & Mensuration › Circles'),
('orig-qa-015', 'QA', 'Polygons & Quadrilaterals', 'MCQ', 'The diagonals of a rhombus are in the ratio 3 : 4 and its area is 384 cm². What is the length of a side?', NULL, '["20 cm", "24 cm", "16 cm", "28 cm"]'::jsonb, '0', '(3k)(4k)/2 = 384 gives k = 8, so the diagonals are 24 and 32. Side = √(12² + 16²) = 20 cm. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10015, 'BANK', now(), 'qa::geometry-mensuration::polygons-quadrilaterals', 'QA › Geometry & Mensuration › Polygons & Quadrilaterals'),
('orig-qa-016', 'QA', 'Circles', 'MCQ', 'A sector of a circle of radius 14 cm subtends an angle of 45° at the centre. What is its arc length? (Use π = 22/7.)', NULL, '["7 cm", "14 cm", "22 cm", "11 cm"]'::jsonb, '3', 'Arc = 2πr × 45/360 = 2 × 22/7 × 14 / 8 = 11 cm. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10016, 'BANK', now(), 'qa::geometry-mensuration::circles', 'QA › Geometry & Mensuration › Circles'),
('orig-qa-017', 'QA', 'Divisibility & Remainders', 'MCQ', 'What is the least positive integer that leaves remainder 2 when divided by 7 and remainder 4 when divided by 11?', NULL, '["48", "37", "114", "26"]'::jsonb, '1', 'Numbers ≡ 4 (mod 11): 4, 15, 26, 37, … The first that leaves 2 on division by 7 is 37. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10017, 'BANK', now(), 'qa::number-system::divisibility-remainders', 'QA › Number System › Divisibility & Remainders'),
('orig-qa-018', 'QA', 'Factors', 'MCQ', 'How many positive divisors does 896 have?', NULL, '["14", "8", "18", "16"]'::jsonb, '3', '896 = 2⁷ × 7, so it has (7 + 1)(1 + 1) = 16 divisors. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10018, 'BANK', now(), 'qa::number-system::factors', 'QA › Number System › Factors'),
('orig-qa-019', 'QA', 'Divisibility & Remainders', 'MCQ', 'What is the remainder when 3¹⁰ + 17⁵ is divided by 26?', NULL, '["3", "1", "0", "23"]'::jsonb, '2', '3³ = 27 ≡ 1 (mod 26), so 3¹⁰ ≡ 3. 17² = 289 ≡ 3, so 17⁴ ≡ 9 and 17⁵ ≡ 153 ≡ 23. The sum is 26 ≡ 0. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10019, 'BANK', now(), 'qa::number-system::divisibility-remainders', 'QA › Number System › Divisibility & Remainders'),
('orig-qa-020', 'QA', 'Factors', 'MCQ', 'How many integers from 1 to 200 (inclusive) are co-prime to 200?', NULL, '["100", "120", "80", "60"]'::jsonb, '2', '200 = 2³ × 5², so φ(200) = 200 × (1/2) × (4/5) = 80. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10020, 'BANK', now(), 'qa::number-system::factors', 'QA › Number System › Factors'),
('orig-qa-021', 'QA', 'Linear equations', 'MCQ', 'The product of two consecutive positive integers is 506. What is the larger integer?', NULL, '["24", "21", "23", "22"]'::jsonb, '2', '22 × 23 = 506, so the larger integer is 23. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10021, 'BANK', now(), 'qa::algebra::linear-equations', 'QA › Algebra › Linear equations'),
('orig-qa-022', 'QA', 'Permutations & Combinations', 'MCQ', 'A committee of 4 is to be chosen from 9 people, 3 of whom are analysts. In how many ways can the committee include at least one analyst?', NULL, '["111", "84", "15", "126"]'::jsonb, '0', 'All committees minus those with no analyst: C(9,4) − C(6,4) = 126 − 15 = 111. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10022, 'BANK', now(), 'qa::modern-maths::permutations-combinations', 'QA › Modern Maths › Permutations & Combinations'),
('orig-qa-023', 'QA', 'Probability', 'MCQ', 'A fair coin is tossed 6 times. What is the probability of getting an even number of heads?', NULL, '["21/64", "11/32", "1/2", "15/32"]'::jsonb, '2', 'For any n ≥ 1, exactly half of the 2ⁿ outcomes have an even number of heads (C(6,0)+C(6,2)+C(6,4)+C(6,6) = 32 of 64). From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10023, 'BANK', now(), 'qa::modern-maths::probability', 'QA › Modern Maths › Probability'),
('orig-qa-024', 'QA', 'Permutations & Combinations', 'MCQ', 'How many 5-digit numbers with all digits distinct are divisible by 5?', NULL, '["6048", "3024", "5712", "5376"]'::jsonb, '2', 'Ending in 0: 9 × 8 × 7 × 6 = 3024. Ending in 5: first digit has 8 choices (not 0 or 5), then 8 × 7 × 6, giving 2688. Total 5712. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10024, 'BANK', now(), 'qa::modern-maths::permutations-combinations', 'QA › Modern Maths › Permutations & Combinations'),
('orig-qa-025', 'QA', 'Permutations & Combinations', 'MCQ', 'In how many ways can 8 identical books be distributed among 4 students so that each student gets at least one book?', NULL, '["35", "165", "56", "70"]'::jsonb, '0', 'Give each student one book, then distribute 4 identical books among 4 students: C(4 + 3, 3) = 35. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10025, 'BANK', now(), 'qa::modern-maths::permutations-combinations', 'QA › Modern Maths › Permutations & Combinations'),
('orig-qa-026', 'QA', 'Probability', 'MCQ', 'An integer is chosen at random from 1 to 81. What is the probability that it is a perfect square or a multiple of 9?', NULL, '["5/27", "2/9", "17/81", "1/9"]'::jsonb, '0', 'There are 9 perfect squares and 9 multiples of 9; 9, 36 and 81 are both. So 15 of 81 qualify: 15/81 = 5/27. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10026, 'BANK', now(), 'qa::modern-maths::probability', 'QA › Modern Maths › Probability'),
('orig-qa-101', 'QA', 'HCF & LCM', 'TITA', 'Three bells ring at intervals of 18, 24 and 32 minutes. If they ring together at 8:00 a.m., after how many minutes will they next ring together?', NULL, NULL, '288', 'LCM(18, 24, 32) = 2⁵ × 3² = 288 minutes. Written for CATalyst.', 'EASY', 10027, 'BANK', now(), 'qa::number-system::hcf-lcm', 'QA › Number System › HCF & LCM'),
('orig-qa-102', 'QA', 'HCF & LCM', 'MCQ', 'The HCF of two numbers is 12 and their LCM is 504. If one of the numbers lies between 80 and 100, what is the other number?', NULL, '["84", "72", "63", "96"]'::jsonb, '1', 'The numbers are 12a and 12b with a, b co-prime and ab = 42. The number between 80 and 100 is 84 (a = 7), so b = 6 and the other number is 72. Written for CATalyst.', 'MODERATE', 10028, 'BANK', now(), 'qa::number-system::hcf-lcm', 'QA › Number System › HCF & LCM'),
('orig-qa-103', 'QA', 'Base systems', 'TITA', 'The number 1234 written in base 5 is converted to base 10. What is the result?', NULL, NULL, '194', '1×125 + 2×25 + 3×5 + 4 = 194. Written for CATalyst.', 'EASY', 10029, 'BANK', now(), 'qa::number-system::base-systems', 'QA › Number System › Base systems'),
('orig-qa-104', 'QA', 'Base systems', 'MCQ', 'The number 2101 in base 3 equals which number in base 10?', NULL, '["58", "61", "64", "70"]'::jsonb, '2', '2×27 + 1×9 + 0×3 + 1 = 64. Written for CATalyst.', 'EASY', 10030, 'BANK', now(), 'qa::number-system::base-systems', 'QA › Number System › Base systems'),
('orig-qa-105', 'QA', 'Unit & last digits', 'TITA', 'What is the unit digit of 7⁹⁹ × 3⁴⁶?', NULL, NULL, '7', 'Powers of 7 end in 7, 9, 3, 1 (a cycle of 4); 99 leaves remainder 3 on division by 4, so 7⁹⁹ ends in 3. Powers of 3 end in 3, 9, 7, 1; 46 leaves remainder 2, so 3⁴⁶ ends in 9. 3 × 9 = 27, so the product ends in 7. Written for CATalyst.', 'MODERATE', 10031, 'BANK', now(), 'qa::number-system::unit-last-digits', 'QA › Number System › Unit & last digits'),
('orig-qa-106', 'QA', 'Unit & last digits', 'TITA', 'What number is formed by the last two digits of 2⁵⁰?', NULL, NULL, '24', '2¹⁰ = 1024 ≡ 24 (mod 100). Then 24² = 576 ≡ 76, and 76 × 76 ≡ 76, so 24⁴ ≡ 76 and 2⁵⁰ = (2¹⁰)⁵ ≡ 24⁵ ≡ 76 × 24 = 1824 ≡ 24. Written for CATalyst.', 'HARD', 10032, 'BANK', now(), 'qa::number-system::unit-last-digits', 'QA › Number System › Unit & last digits'),
('orig-qa-107', 'QA', 'Factors', 'TITA', 'How many factors of 2160 are perfect squares?', NULL, NULL, '6', '2160 = 2⁴ × 3³ × 5. A square factor needs even exponents: 2 has 3 choices (0, 2, 4), 3 has 2 (0, 2) and 5 has 1 (0), so 3 × 2 × 1 = 6. Written for CATalyst.', 'MODERATE', 10033, 'BANK', now(), 'qa::number-system::factors', 'QA › Number System › Factors'),
('orig-qa-108', 'QA', 'Coordinate geometry', 'MCQ', 'What is the area of the triangle with vertices (1, 2), (5, 6) and (7, 1)?', NULL, '["16", "14", "12", "18"]'::jsonb, '1', 'Area = ½|1(6 − 1) + 5(1 − 2) + 7(2 − 6)| = ½|5 − 5 − 28| = 14. Written for CATalyst.', 'MODERATE', 10034, 'BANK', now(), 'qa::geometry-mensuration::coordinate-geometry', 'QA › Geometry & Mensuration › Coordinate geometry'),
('orig-qa-109', 'QA', 'Coordinate geometry', 'MCQ', 'The line through (2, 3) perpendicular to 3x − 4y + 5 = 0 meets the x-axis at which point?', NULL, '["(17/4, 0)", "(6, 0)", "(−2, 0)", "(9/4, 0)"]'::jsonb, '0', 'The given line has slope 3/4, so the perpendicular has slope −4/3: y − 3 = −(4/3)(x − 2). Setting y = 0 gives x = 2 + 9/4 = 17/4. Written for CATalyst.', 'MODERATE', 10035, 'BANK', now(), 'qa::geometry-mensuration::coordinate-geometry', 'QA › Geometry & Mensuration › Coordinate geometry'),
('orig-qa-110', 'QA', 'Trigonometry basics', 'MCQ', 'From a point 30 m from the foot of a tower, the angle of elevation of its top is 60°. What is the height of the tower?', NULL, '["30√3 m", "60 m", "15√3 m", "10√3 m"]'::jsonb, '0', 'tan 60° = h/30, so h = 30√3 m. Written for CATalyst.', 'EASY', 10036, 'BANK', now(), 'qa::geometry-mensuration::trigonometry-basics', 'QA › Geometry & Mensuration › Trigonometry basics'),
('orig-qa-111', 'QA', 'Trigonometry basics', 'TITA', 'If sin θ + cos θ = 7/5 for an acute angle θ, what is the value of sin θ · cos θ? (Enter as a decimal.)', NULL, NULL, '0.48', 'Squaring: 1 + 2 sin θ cos θ = 49/25, so sin θ cos θ = 24/50 = 0.48. Written for CATalyst.', 'MODERATE', 10037, 'BANK', now(), 'qa::geometry-mensuration::trigonometry-basics', 'QA › Geometry & Mensuration › Trigonometry basics'),
('orig-qa-112', 'QA', 'Logarithms', 'TITA', 'If log₂(x − 1) + log₂(x + 1) = 3, what is x?', NULL, NULL, '3', 'log₂(x² − 1) = 3 gives x² = 9; x must exceed 1, so x = 3. Written for CATalyst.', 'EASY', 10038, 'BANK', now(), 'qa::algebra::logarithms', 'QA › Algebra › Logarithms'),
('orig-qa-113', 'QA', 'Logarithms', 'MCQ', 'What is the value of log₃ 5 × log₂₅ 27?', NULL, '["3/5", "5/3", "3/2", "2/3"]'::jsonb, '2', 'log₃ 5 × (3 log 3)/(2 log 5) = 3/2. Written for CATalyst.', 'MODERATE', 10039, 'BANK', now(), 'qa::algebra::logarithms', 'QA › Algebra › Logarithms'),
('orig-qa-114', 'QA', 'Progressions (AP/GP/HP)', 'TITA', 'The 5th term of an arithmetic progression is 23 and its 12th term is 51. What is the sum of its first 20 terms?', NULL, NULL, '900', 'd = (51 − 23)/7 = 4 and a = 23 − 16 = 7. S₂₀ = 10(2×7 + 19×4) = 10 × 90 = 900. Written for CATalyst.', 'MODERATE', 10040, 'BANK', now(), 'qa::algebra::progressions-ap-gp-hp-', 'QA › Algebra › Progressions (AP/GP/HP)'),
('orig-qa-115', 'QA', 'Progressions (AP/GP/HP)', 'MCQ', 'The sum to infinity of a geometric progression is 24 and its first term is 16. What is its common ratio?', NULL, '["1/4", "1/2", "1/3", "2/3"]'::jsonb, '2', '16/(1 − r) = 24 gives 1 − r = 2/3, so r = 1/3. Written for CATalyst.', 'MODERATE', 10041, 'BANK', now(), 'qa::algebra::progressions-ap-gp-hp-', 'QA › Algebra › Progressions (AP/GP/HP)'),
('orig-qa-116', 'QA', 'Sequences & Series', 'TITA', 'A sequence is defined by a₁ = 1 and aₙ₊₁ = aₙ + 2n for n ≥ 1. What is a₁₀?', NULL, NULL, '91', 'aₙ = 1 + 2(1 + 2 + … + (n − 1)) = 1 + n(n − 1), so a₁₀ = 1 + 90 = 91. Written for CATalyst.', 'MODERATE', 10042, 'BANK', now(), 'qa::modern-maths::sequences-series', 'QA › Modern Maths › Sequences & Series'),
('orig-qa-117', 'QA', 'Sequences & Series', 'MCQ', 'What is the value of 1/(1·2) + 1/(2·3) + 1/(3·4) + … + 1/(24·25)?', NULL, '["25/26", "23/24", "1", "24/25"]'::jsonb, '3', 'Each term is 1/k − 1/(k + 1), so the sum telescopes to 1 − 1/25 = 24/25. Written for CATalyst.', 'MODERATE', 10043, 'BANK', now(), 'qa::modern-maths::sequences-series', 'QA › Modern Maths › Sequences & Series'),
('orig-qa-118', 'QA', 'Inequalities & Modulus', 'MCQ', 'How many integers x satisfy |2x − 7| < 9?', NULL, '["8", "10", "9", "7"]'::jsonb, '0', '−9 < 2x − 7 < 9 gives −1 < x < 8, so x = 0, 1, …, 7: 8 integers. Written for CATalyst.', 'MODERATE', 10044, 'BANK', now(), 'qa::algebra::inequalities-modulus', 'QA › Algebra › Inequalities & Modulus'),
('orig-qa-119', 'QA', 'Inequalities & Modulus', 'TITA', 'What is the minimum value of |x − 2| + |x − 5| + |x − 11|?', NULL, NULL, '9', 'The sum is smallest at the median point x = 5: 3 + 0 + 6 = 9. Written for CATalyst.', 'MODERATE', 10045, 'BANK', now(), 'qa::algebra::inequalities-modulus', 'QA › Algebra › Inequalities & Modulus'),
('orig-qa-120', 'QA', 'Functions & Graphs', 'MCQ', 'If f(x) = 2x + 3 and g(x) = x² − 1, what is f(g(2)) − g(f(2))?', NULL, '["−41", "39", "41", "−39"]'::jsonb, '3', 'g(2) = 3 so f(g(2)) = 9; f(2) = 7 so g(f(2)) = 48. 9 − 48 = −39. Written for CATalyst.', 'MODERATE', 10046, 'BANK', now(), 'qa::algebra::functions-graphs', 'QA › Algebra › Functions & Graphs'),
('orig-qa-121', 'QA', 'Functions & Graphs', 'TITA', 'A function satisfies f(x) + 2f(1 − x) = 3x for all real x. What is f(0)?', NULL, NULL, '2', 'At x = 0: f(0) + 2f(1) = 0. At x = 1: f(1) + 2f(0) = 3. Solving, f(0) = 2 and f(1) = −1. Written for CATalyst.', 'HARD', 10047, 'BANK', now(), 'qa::algebra::functions-graphs', 'QA › Algebra › Functions & Graphs'),
('orig-qa-122', 'QA', 'Set theory', 'MCQ', 'In a group of 60 students, 35 play cricket, 28 play football and 12 play neither. How many play both?', NULL, '["11", "15", "13", "17"]'::jsonb, '1', 'Students playing at least one = 48 = 35 + 28 − both, so both = 15. Written for CATalyst.', 'EASY', 10048, 'BANK', now(), 'qa::modern-maths::set-theory', 'QA › Modern Maths › Set theory'),
('orig-qa-123', 'QA', 'Probability', 'TITA', 'Two dice are thrown. What is the probability that the sum is a prime number? (Enter as a decimal rounded to three places.)', NULL, NULL, '0.417', 'Prime sums 2, 3, 5, 7, 11 occur in 1 + 2 + 4 + 6 + 2 = 15 of 36 outcomes: 15/36 ≈ 0.417. Written for CATalyst.', 'MODERATE', 10049, 'BANK', now(), 'qa::modern-maths::probability', 'QA › Modern Maths › Probability'),
('orig-qa-124', 'QA', 'Probability', 'MCQ', 'A bag has 5 red and 4 blue balls. Two balls are drawn without replacement. What is the probability that they are of different colours?', NULL, '["5/9", "20/81", "1/2", "4/9"]'::jsonb, '0', '(5 × 4)/C(9, 2) = 20/36 = 5/9. Written for CATalyst.', 'MODERATE', 10050, 'BANK', now(), 'qa::modern-maths::probability', 'QA › Modern Maths › Probability'),
('orig-qa-125', 'QA', 'Permutations & Combinations', 'TITA', 'In how many ways can the letters of the word BANANA be arranged?', NULL, NULL, '60', '6!/(3! × 2!) = 720/12 = 60. Written for CATalyst.', 'EASY', 10051, 'BANK', now(), 'qa::modern-maths::permutations-combinations', 'QA › Modern Maths › Permutations & Combinations'),
('orig-qa-126', 'QA', 'Percentages', 'MCQ', 'A town’s population rises by 20% in one year and falls by 20% the next, ending at 9,600. What was it at the start?', NULL, '["10,400", "9,216", "9,600", "10,000"]'::jsonb, '3', 'P × 1.2 × 0.8 = 0.96P = 9600, so P = 10,000. Written for CATalyst.', 'EASY', 10052, 'BANK', now(), 'qa::arithmetic::percentages', 'QA › Arithmetic › Percentages'),
('orig-qa-127', 'QA', 'Percentages', 'TITA', 'The price of sugar rises by 25%. By what percentage must a household reduce its consumption so that its spending on sugar does not change?', NULL, NULL, '20', 'Consumption must become 1/1.25 = 0.8 of the original, a 20% cut. Written for CATalyst.', 'MODERATE', 10053, 'BANK', now(), 'qa::arithmetic::percentages', 'QA › Arithmetic › Percentages'),
('orig-qa-128', 'QA', 'Profit, Loss & Discount', 'TITA', 'A trader sells an article at a 25% discount on its marked price and still makes a 20% profit. If the cost price is ₹600, what is the marked price in rupees?', NULL, NULL, '960', 'Selling price = 1.2 × 600 = 720 = 0.75 × marked price, so the marked price is ₹960. Written for CATalyst.', 'MODERATE', 10054, 'BANK', now(), 'qa::arithmetic::profit-loss-discount', 'QA › Arithmetic › Profit, Loss & Discount'),
('orig-qa-129', 'QA', 'Simple & Compound Interest', 'MCQ', 'The difference between compound and simple interest on a sum for 2 years at 10% per annum is ₹50. What is the sum?', NULL, '["₹500", "₹10,000", "₹5,000", "₹2,500"]'::jsonb, '2', 'For two years, CI − SI = P(r/100)² = 0.01P = 50, so P = ₹5,000. Written for CATalyst.', 'MODERATE', 10055, 'BANK', now(), 'qa::arithmetic::simple-compound-interest', 'QA › Arithmetic › Simple & Compound Interest'),
('orig-qa-130', 'QA', 'Time & Work', 'TITA', 'A can finish a job in 12 days and B in 18 days. They work together for 4 days, after which A leaves. In how many more days will B finish the job?', NULL, NULL, '8', 'Together they do 1/12 + 1/18 = 5/36 a day, so 20/36 in 4 days. B finishes the remaining 16/36 at 1/18 a day in 8 days. Written for CATalyst.', 'MODERATE', 10056, 'BANK', now(), 'qa::arithmetic::time-work', 'QA › Arithmetic › Time & Work'),
('orig-qa-131', 'QA', 'Time & Work', 'MCQ', 'Pipe A fills a tank in 6 hours and pipe B in 8 hours, while pipe C empties it in 12 hours. If all three are opened together on an empty tank, how long will it take to fill?', NULL, '["4 h 48 min", "4 h 30 min", "5 h", "3 h 36 min"]'::jsonb, '0', 'Net rate = 1/6 + 1/8 − 1/12 = 5/24 per hour, so the tank fills in 24/5 h = 4 h 48 min. Written for CATalyst.', 'MODERATE', 10057, 'BANK', now(), 'qa::arithmetic::time-work', 'QA › Arithmetic › Time & Work'),
('orig-qa-132', 'QA', 'Time, Speed & Distance', 'TITA', 'Two trains 150 m and 100 m long run in opposite directions at 54 km/h and 36 km/h. How many seconds do they take to cross each other completely?', NULL, NULL, '10', 'Relative speed = 90 km/h = 25 m/s; the combined length is 250 m, so they take 10 s. Written for CATalyst.', 'MODERATE', 10058, 'BANK', now(), 'qa::arithmetic::time-speed-distance', 'QA › Arithmetic › Time, Speed & Distance'),
('orig-qa-133', 'QA', 'Time, Speed & Distance', 'MCQ', 'A boat goes 24 km upstream in 6 hours and 30 km downstream in 3 hours. What is the speed of the stream?', NULL, '["7 km/h", "3 km/h", "2 km/h", "4 km/h"]'::jsonb, '1', 'Upstream speed = 4 km/h and downstream speed = 10 km/h, so the stream flows at (10 − 4)/2 = 3 km/h. Written for CATalyst.', 'MODERATE', 10059, 'BANK', now(), 'qa::arithmetic::time-speed-distance', 'QA › Arithmetic › Time, Speed & Distance'),
('orig-qa-134', 'QA', 'Averages', 'TITA', 'The average of 11 numbers is 50. The average of the first six is 49 and of the last six is 52. What is the sixth number?', NULL, NULL, '56', 'Sum of all = 550. First six + last six = 294 + 312 = 606, which counts the sixth number twice, so it is 606 − 550 = 56. Written for CATalyst.', 'MODERATE', 10060, 'BANK', now(), 'qa::arithmetic::averages', 'QA › Arithmetic › Averages'),
('orig-qa-135', 'QA', 'Averages', 'MCQ', 'A batsman’s average after 16 innings rises by 3 when he scores 87 in his 17th innings. What is his average after 17 innings?', NULL, '["36", "45", "42", "39"]'::jsonb, '3', 'If the average after 16 innings is a, then 16a + 87 = 17(a + 3), so a = 36 and the new average is 39. Written for CATalyst.', 'MODERATE', 10061, 'BANK', now(), 'qa::arithmetic::averages', 'QA › Arithmetic › Averages'),
('orig-qa-136', 'QA', 'Ratio & Proportion', 'TITA', '₹7,700 is divided among A, B and C so that A : B = 2 : 3 and B : C = 4 : 5. What is C’s share in rupees?', NULL, NULL, '3300', 'A : B : C = 8 : 12 : 15, a total of 35 parts, so C gets 7700 × 15/35 = ₹3,300. Written for CATalyst.', 'MODERATE', 10062, 'BANK', now(), 'qa::arithmetic::ratio-proportion', 'QA › Arithmetic › Ratio & Proportion'),
('orig-qa-137', 'QA', 'Mixtures & Alligation', 'MCQ', 'In what ratio must rice costing ₹42/kg be mixed with rice costing ₹54/kg so that the mixture costs ₹46/kg?', NULL, '["3 : 2", "1 : 2", "2 : 1", "4 : 3"]'::jsonb, '2', 'By alligation, (54 − 46) : (46 − 42) = 8 : 4 = 2 : 1. Written for CATalyst.', 'EASY', 10063, 'BANK', now(), 'qa::arithmetic::mixtures-alligation', 'QA › Arithmetic › Mixtures & Alligation'),
('orig-qa-138', 'QA', 'Mixtures & Alligation', 'TITA', 'A 40-litre mixture contains milk and water in the ratio 3 : 1. How many litres of water must be added to make the ratio 2 : 1?', NULL, NULL, '5', 'Milk = 30 L and water = 10 L. For milk : water = 2 : 1, water must be 15 L, so add 5 L. Written for CATalyst.', 'MODERATE', 10064, 'BANK', now(), 'qa::arithmetic::mixtures-alligation', 'QA › Arithmetic › Mixtures & Alligation'),
('orig-qa-139', 'QA', 'Triangles', 'MCQ', 'In a right triangle the legs are 20 and 21. What is the radius of its inscribed circle?', NULL, '["7", "8", "5", "6"]'::jsonb, '3', 'Hypotenuse = 29. For a right triangle, r = (a + b − c)/2 = (20 + 21 − 29)/2 = 6. Written for CATalyst.', 'MODERATE', 10065, 'BANK', now(), 'qa::geometry-mensuration::triangles', 'QA › Geometry & Mensuration › Triangles'),
('orig-qa-140', 'QA', 'Polygons & Quadrilaterals', 'TITA', 'Each interior angle of a regular polygon is 156°. How many sides does it have?', NULL, NULL, '15', 'Each exterior angle is 24°, and 360/24 = 15. Written for CATalyst.', 'EASY', 10066, 'BANK', now(), 'qa::geometry-mensuration::polygons-quadrilaterals', 'QA › Geometry & Mensuration › Polygons & Quadrilaterals'),
('orig-qa-141', 'QA', '3D Mensuration', 'MCQ', 'A cone and a hemisphere have equal bases and equal volumes. What is the ratio of the height of the cone to its base radius?', NULL, '["3 : 1", "2 : 1", "1 : 1", "1 : 2"]'::jsonb, '1', '(1/3)πr²h = (2/3)πr³ gives h = 2r. Written for CATalyst.', 'MODERATE', 10067, 'BANK', now(), 'qa::geometry-mensuration::3d-mensuration', 'QA › Geometry & Mensuration › 3D Mensuration'),
('orig-qa-142', 'QA', 'Linear equations', 'MCQ', 'The sum of the digits of a two-digit number is 11. Reversing the digits increases the number by 27. What is the number?', NULL, '["38", "47", "74", "56"]'::jsonb, '1', 'If the number is 10a + b, then a + b = 11 and 9(b − a) = 27, so b − a = 3, giving a = 4, b = 7: the number is 47. Written for CATalyst.', 'MODERATE', 10068, 'BANK', now(), 'qa::algebra::linear-equations', 'QA › Algebra › Linear equations'),
('orig-dilr-s01-q1', 'DILR', 'Tables & Caselets', 'TITA', 'How many students are admitted in total?', 'Admissions allocation

A university allocates 120 seats across four programmes P, Q, R and S. P has 10 more seats than Q, R has twice as many seats as Q, and S has 10 fewer seats than R. Each programme fills 80% of its seats, except Q, which fills 75%.', NULL, '95', 'Q + 10 + Q + 2Q + 2Q − 10 = 120 gives Q = 20, so P = 30, R = 40, S = 30. Admitted: 24 + 15 + 32 + 24 = 95. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10069, 'BANK', now(), 'dilr::data-interpretation::tables-caselets', 'DILR › Data Interpretation › Tables & Caselets'),
('orig-dilr-s01-q2', 'DILR', 'Tables & Caselets', 'MCQ', 'Which programme has the most unfilled seats?', 'Admissions allocation

A university allocates 120 seats across four programmes P, Q, R and S. P has 10 more seats than Q, R has twice as many seats as Q, and S has 10 fewer seats than R. Each programme fills 80% of its seats, except Q, which fills 75%.', '["P", "S", "R", "Q"]'::jsonb, '2', 'Unfilled seats: P 6, Q 5, R 8, S 6. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10070, 'BANK', now(), 'dilr::data-interpretation::tables-caselets', 'DILR › Data Interpretation › Tables & Caselets'),
('orig-dilr-s01-q3', 'DILR', 'Tables & Caselets', 'MCQ', 'If R’s capacity is increased by 10 seats and it still fills 80% of its seats, what percentage of all seats is filled?', 'Admissions allocation

A university allocates 120 seats across four programmes P, Q, R and S. P has 10 more seats than Q, R has twice as many seats as Q, and S has 10 fewer seats than R. Each programme fills 80% of its seats, except Q, which fills 75%.', '["73.08%", "80.00%", "79.17%", "79.23%"]'::jsonb, '3', 'Seats = 130 and admitted = 95 + 8 = 103, so 103/130 = 79.23%. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'HARD', 10071, 'BANK', now(), 'dilr::data-interpretation::tables-caselets', 'DILR › Data Interpretation › Tables & Caselets'),
('orig-dilr-s02-q1', 'DILR', 'Tables & Caselets', 'TITA', 'How many defective units do the three factories produce in all?', 'Factory production

Three factories A, B and C produce components X and Y. Their total output of 2,700 units is split in the ratio 2 : 3 : 4. Component X makes up 60% of A’s output, 50% of B’s and 40% of C’s. The defect rate for X is 5% at A, 2% at B and 5% at C; for Y it is 5% at A, 2% at B and 2.5% at C.', NULL, '90', 'Outputs 600, 900, 1200. Defective X: 18 + 9 + 24 = 51; defective Y: 12 + 9 + 18 = 39. Total 90. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10072, 'BANK', now(), 'dilr::data-interpretation::tables-caselets', 'DILR › Data Interpretation › Tables & Caselets'),
('orig-dilr-s02-q2', 'DILR', 'Tables & Caselets', 'MCQ', 'Which factory has the highest overall defect rate?', 'Factory production

Three factories A, B and C produce components X and Y. Their total output of 2,700 units is split in the ratio 2 : 3 : 4. Component X makes up 60% of A’s output, 50% of B’s and 40% of C’s. The defect rate for X is 5% at A, 2% at B and 5% at C; for Y it is 5% at A, 2% at B and 2.5% at C.', '["C", "A", "B", "A and C equally"]'::jsonb, '1', 'A: 30/600 = 5%; B: 18/900 = 2%; C: 42/1200 = 3.5%. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10073, 'BANK', now(), 'dilr::data-interpretation::tables-caselets', 'DILR › Data Interpretation › Tables & Caselets'),
('orig-dilr-s02-q3', 'DILR', 'Tables & Caselets', 'MCQ', 'What share of all defective units are component Y?', 'Factory production

Three factories A, B and C produce components X and Y. Their total output of 2,700 units is split in the ratio 2 : 3 : 4. Component X makes up 60% of A’s output, 50% of B’s and 40% of C’s. The defect rate for X is 5% at A, 2% at B and 5% at C; for Y it is 5% at A, 2% at B and 2.5% at C.', '["46.67%", "56.67%", "43.33%", "39.00%"]'::jsonb, '2', '39 of the 90 defective units are Y: 43.33%. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'HARD', 10074, 'BANK', now(), 'dilr::data-interpretation::tables-caselets', 'DILR › Data Interpretation › Tables & Caselets'),
('orig-dilr-s03-q1', 'DILR', 'Quant-based LR', 'TITA', 'How many subscribers watch live content?', 'Streaming subscriptions

A streaming platform has 10,000 subscribers on Basic, Plus and Pro plans in the ratio 5 : 3 : 2. 40% of Basic, 60% of Plus and 80% of Pro subscribers use the mobile app. 30% of mobile-app users watch live content, against 20% of the other subscribers.', NULL, '2540', 'Mobile users: 2000 + 1800 + 1600 = 5400; others 4600. Live: 1620 + 920 = 2540. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10075, 'BANK', now(), 'dilr::logical-reasoning::quant-based-lr', 'DILR › Logical Reasoning › Quant-based LR'),
('orig-dilr-s03-q2', 'DILR', 'Quant-based LR', 'MCQ', 'What percentage of mobile-app users are on the Pro plan?', 'Streaming subscriptions

A streaming platform has 10,000 subscribers on Basic, Plus and Pro plans in the ratio 5 : 3 : 2. 40% of Basic, 60% of Plus and 80% of Pro subscribers use the mobile app. 30% of mobile-app users watch live content, against 20% of the other subscribers.', '["29.63%", "20.00%", "80.00%", "33.33%"]'::jsonb, '0', '1600 of 5400 mobile users are Pro: 29.63%. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10076, 'BANK', now(), 'dilr::logical-reasoning::quant-based-lr', 'DILR › Logical Reasoning › Quant-based LR'),
('orig-dilr-s03-q3', 'DILR', 'Quant-based LR', 'TITA', 'If 55% of Basic subscribers used the mobile app (other figures unchanged), by how many would the number of live viewers increase?', 'Streaming subscriptions

A streaming platform has 10,000 subscribers on Basic, Plus and Pro plans in the ratio 5 : 3 : 2. 40% of Basic, 60% of Plus and 80% of Pro subscribers use the mobile app. 30% of mobile-app users watch live content, against 20% of the other subscribers.', NULL, '75', '750 more Basic subscribers move from the 20% group to the 30% group: 750 × 10% = 75. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'HARD', 10077, 'BANK', now(), 'dilr::logical-reasoning::quant-based-lr', 'DILR › Logical Reasoning › Quant-based LR'),
('orig-dilr-s04-q1', 'DILR', 'Games & Tournaments', 'MCQ', 'How many teams finish with exactly 7 points?', 'Tournament table

Six teams A–F play a round-robin tournament, each pair meeting once. A win earns 3 points and a draw 1 point to each team. A beats B, C and D, loses to E and draws with F. B beats C and D, draws with E and loses to F. C beats D and E and loses to F. D beats E and F. E beats F.', '["3", "4", "1", "2"]'::jsonb, '0', 'Points: A 10, B 7, C 6, D 6, E 7, F 7. B, E and F have 7. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10078, 'BANK', now(), 'dilr::logical-reasoning::games-tournaments', 'DILR › Logical Reasoning › Games & Tournaments'),
('orig-dilr-s04-q2', 'DILR', 'Games & Tournaments', 'TITA', 'How many points are awarded in the tournament in total?', 'Tournament table

Six teams A–F play a round-robin tournament, each pair meeting once. A win earns 3 points and a draw 1 point to each team. A beats B, C and D, loses to E and draws with F. B beats C and D, draws with E and loses to F. C beats D and E and loses to F. D beats E and F. E beats F.', NULL, '43', '13 decided matches × 3 + 2 draws × 2 = 43. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10079, 'BANK', now(), 'dilr::logical-reasoning::games-tournaments', 'DILR › Logical Reasoning › Games & Tournaments'),
('orig-dilr-s04-q3', 'DILR', 'Games & Tournaments', 'MCQ', 'Had E beaten B instead of drawing, which team would have finished second?', 'Tournament table

Six teams A–F play a round-robin tournament, each pair meeting once. A win earns 3 points and a draw 1 point to each team. A beats B, C and D, loses to E and draws with F. B beats C and D, draws with E and loses to F. C beats D and E and loses to F. D beats E and F. E beats F.', '["E", "F", "B", "A"]'::jsonb, '0', 'E would have 9 points, behind A’s 10 and ahead of everyone else. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'HARD', 10080, 'BANK', now(), 'dilr::logical-reasoning::games-tournaments', 'DILR › Logical Reasoning › Games & Tournaments'),
('orig-dilr-s05-q1', 'DILR', 'Networks & Routes', 'MCQ', 'Which zone receives the fewest deliveries?', 'Delivery routes

Five depots A–E deliver to zones 1–5. Each depot serves exactly two zones and splits its daily deliveries equally between them: A serves zones 1 and 2, B serves 2 and 3, C serves 3 and 4, D serves 4 and 5, and E serves 5 and 1. Daily deliveries are A 40, B 60, C 50, D 30 and E 70.', '["Zone 2", "Zone 5", "Zone 4", "Zone 1"]'::jsonb, '2', 'Zone totals: 1 → 55, 2 → 50, 3 → 55, 4 → 40, 5 → 50. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10081, 'BANK', now(), 'dilr::logical-reasoning::networks-routes', 'DILR › Logical Reasoning › Networks & Routes'),
('orig-dilr-s05-q2', 'DILR', 'Networks & Routes', 'MCQ', 'If depot E doubled its deliveries, how many zones would receive more than 50 deliveries?', 'Delivery routes

Five depots A–E deliver to zones 1–5. Each depot serves exactly two zones and splits its daily deliveries equally between them: A serves zones 1 and 2, B serves 2 and 3, C serves 3 and 4, D serves 4 and 5, and E serves 5 and 1. Daily deliveries are A 40, B 60, C 50, D 30 and E 70.', '["2", "1", "4", "3"]'::jsonb, '3', 'E sends 70 to each of zones 1 and 5: zone 1 → 90, zone 5 → 85; zone 3 stays at 55. Three zones exceed 50. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10082, 'BANK', now(), 'dilr::logical-reasoning::networks-routes', 'DILR › Logical Reasoning › Networks & Routes'),
('orig-dilr-s05-q3', 'DILR', 'Networks & Routes', 'TITA', 'How many deliveries do zones 1, 3 and 5 receive together?', 'Delivery routes

Five depots A–E deliver to zones 1–5. Each depot serves exactly two zones and splits its daily deliveries equally between them: A serves zones 1 and 2, B serves 2 and 3, C serves 3 and 4, D serves 4 and 5, and E serves 5 and 1. Daily deliveries are A 40, B 60, C 50, D 30 and E 70.', NULL, '160', '55 + 55 + 50 = 160. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'HARD', 10083, 'BANK', now(), 'dilr::logical-reasoning::networks-routes', 'DILR › Logical Reasoning › Networks & Routes'),
('orig-dilr-s06-q1', 'DILR', 'Arrangements (linear/circular)', 'MCQ', 'Who scored 240?', 'Exam scores

Four candidates P, Q, R and S took an exam. Their total scores were 210, 225, 240 and 255, in some order. P scored more than Q but less than R. S did not have the lowest score. Q did not score 225. R scored exactly 15 more than S.', '["P", "Q", "S", "R"]'::jsonb, '2', 'Q must be lowest (210). With R = S + 15 and P < R, the only order is Q 210, P 225, S 240, R 255. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10084, 'BANK', now(), 'dilr::logical-reasoning::arrangements-linear-circular-', 'DILR › Logical Reasoning › Arrangements (linear/circular)'),
('orig-dilr-s06-q2', 'DILR', 'Arrangements (linear/circular)', 'TITA', 'By how many marks did S outscore P?', 'Exam scores

Four candidates P, Q, R and S took an exam. Their total scores were 210, 225, 240 and 255, in some order. P scored more than Q but less than R. S did not have the lowest score. Q did not score 225. R scored exactly 15 more than S.', NULL, '15', 'S 240 − P 225 = 15. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10085, 'BANK', now(), 'dilr::logical-reasoning::arrangements-linear-circular-', 'DILR › Logical Reasoning › Arrangements (linear/circular)'),
('orig-dilr-s06-q3', 'DILR', 'Arrangements (linear/circular)', 'MCQ', 'If the last condition (R scored 15 more than S) were removed, how many orders of scores would be possible?', 'Exam scores

Four candidates P, Q, R and S took an exam. Their total scores were 210, 225, 240 and 255, in some order. P scored more than Q but less than R. S did not have the lowest score. Q did not score 225. R scored exactly 15 more than S.', '["2", "3", "4", "1"]'::jsonb, '1', 'Q is still 210; P, R, S can be (225, 240, 255), (225, 255, 240) or (240, 255, 225). From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'HARD', 10086, 'BANK', now(), 'dilr::logical-reasoning::arrangements-linear-circular-', 'DILR › Logical Reasoning › Arrangements (linear/circular)'),
('orig-dilr-s07-q1', 'DILR', 'Scheduling & Calendars', 'MCQ', 'Who works the same shift as A?', 'Warehouse shifts

Six workers A–F are each assigned to one of three shifts (morning, afternoon, night), two workers per shift. C and D work the same shift. A and B work different shifts. E works the morning shift. A does not work the morning shift, B does not work the afternoon shift, and F does not work the night shift.', '["E", "F", "C", "B"]'::jsonb, '1', 'C and D cannot share the morning with E, and the only consistent assignment is morning E, B; afternoon A, F; night C, D. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10087, 'BANK', now(), 'dilr::logical-reasoning::scheduling-calendars', 'DILR › Logical Reasoning › Scheduling & Calendars'),
('orig-dilr-s07-q2', 'DILR', 'Scheduling & Calendars', 'MCQ', 'Which shift do C and D work?', 'Warehouse shifts

Six workers A–F are each assigned to one of three shifts (morning, afternoon, night), two workers per shift. C and D work the same shift. A and B work different shifts. E works the morning shift. A does not work the morning shift, B does not work the afternoon shift, and F does not work the night shift.', '["Morning", "Afternoon", "Cannot be determined", "Night"]'::jsonb, '3', 'See the unique assignment above. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10088, 'BANK', now(), 'dilr::logical-reasoning::scheduling-calendars', 'DILR › Logical Reasoning › Scheduling & Calendars'),
('orig-dilr-s07-q3', 'DILR', 'Scheduling & Calendars', 'TITA', 'If the condition on F were removed, how many valid assignments would there be?', 'Warehouse shifts

Six workers A–F are each assigned to one of three shifts (morning, afternoon, night), two workers per shift. C and D work the same shift. A and B work different shifts. E works the morning shift. A does not work the morning shift, B does not work the afternoon shift, and F does not work the night shift.', NULL, '2', 'C and D could then also take the afternoon shift, with A and F on nights and B in the morning. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'HARD', 10089, 'BANK', now(), 'dilr::logical-reasoning::scheduling-calendars', 'DILR › Logical Reasoning › Scheduling & Calendars'),
('orig-dilr-s08-q1', 'DILR', 'Tables & Caselets', 'MCQ', 'What is the portfolio worth at the end of year one?', 'Investment portfolio

An investor splits ₹9 lakh among equity, debt and gold. The equity amount is twice the debt amount, and gold is ₹1 lakh less than equity. In year one the investments return +12%, +7% and +5% respectively. In year two equity falls 10%, debt rises 6% and gold is unchanged.', '["₹9.72 lakh", "₹9.45 lakh", "₹9.81 lakh", "₹9.77 lakh"]'::jsonb, '3', 'Equity 4, debt 2, gold 3 lakh. After year one: 4.48 + 2.14 + 3.15 = ₹9.77 lakh. From the CAT 2026 Original Advanced Question Bank (cleaned and verified).', 'MODERATE', 10090, 'BANK', now(), 'dilr::data-interpretation::tables-caselets', 'DILR › Data Interpretation › Tables & Caselets'),
('orig-dilr-s08-q2', 'DILR', 'Tables & Caselets', 'MCQ', 'What is the overall percentage gain after two years?', 'Investment portfolio

